const paths = Array.from({length:4}, (_, index) => document.querySelector('#route' + index));
const packet = document.querySelector('#packet');
const status = document.querySelector('#status');
const messages = ['1 / 4  Agent saves separate HTML, CSS and JavaScript fields.', '2 / 4  Play mounts a Code OSS webview with a sandboxed animation iframe.', '3 / 4  The browser draws directly; CSP restricts requests, with no native filter.', '4 / 4  Click any box to explore code; Restart loads the latest saved scene.'];
let previousStep = -1;
animation.onFrame(({elapsedMs}) => {
  const phase = (elapsedMs / 2200) % 4;
  const step = Math.floor(phase);
  const progress = phase - step;
  const point = paths[step].getPointAtLength(paths[step].getTotalLength() * progress);
  packet.setAttribute('cx', point.x);
  packet.setAttribute('cy', point.y);
  if (step !== previousStep) { status.textContent = messages[step]; previousStep = step; }
});
